import type { IngredientUnit, NutrientsPer100 } from './project73';

/** Where product data came from. 'demo' data is generated by the mock adapter and never real. */
export type ProductSource = 'picnic' | 'demo';

export interface ProductCandidate {
  productId: string;
  name: string;
  brand: string | null;
  unitQuantity: string;
  priceCents: number;
  originalPriceCents: number | null;
  unitPriceText: string | null;
  imageUrl: string | null;
  isUnavailable: boolean;
  maxCount: number;
  boughtBefore: boolean;
  promoLabel: string | null;
  source: ProductSource;
}

export interface ProductDetails {
  productId: string;
  nutritionPer100: NutrientsPer100 | null;
  allergensContains: string[];
  allergensMayContain: string[];
  retrievedAt: string;
  source: ProductSource;
}

export interface RequirementMealRef { mealId: string; date: string; recipeName: string; amount: number }

export interface IngredientRequirement {
  ingredientId: string;
  name: string;
  unit: IngredientUnit;
  /** Total needed for the planned meals. */
  amount: number;
  /** Part of the need already covered by the pantry. */
  pantryAmount: number;
  /** What still has to be bought. */
  netAmount: number;
  staple: boolean;
  meals: RequirementMealRef[];
}

export type ShoppingItemStatus = 'matched' | 'unavailable' | 'no_match' | 'covered_by_pantry' | 'staple_at_home' | 'removed' | 'search_failed';

export interface RankedCandidate {
  product: ProductCandidate;
  /** Usable amount per package in the ingredient unit. */
  coverage: number;
  score: number;
  reasons: string[];
}

export interface ShoppingItem {
  ingredientId: string;
  name: string;
  unit: IngredientUnit;
  neededAmount: number;
  pantryAmount: number;
  netAmount: number;
  status: ShoppingItemStatus;
  lines: Array<{ product: ProductCandidate; count: number; coverage: number }>;
  alternatives: RankedCandidate[];
  purchasedAmount: number;
  surplusAmount: number;
  costCents: number;
  consumedCostCents: number;
  wasteRisk: 'none' | 'low' | 'high';
  manual: boolean;
  nutritionVerified: boolean;
  /** Per-100 label of the chosen Picnic product, when complete. Never set for demo data. */
  nutritionPer100?: NutrientsPer100 | null;
  note?: string;
  meals: RequirementMealRef[];
}

export interface ShoppingTotals {
  costCents: number;
  consumedCostCents: number;
  surplusCostCents: number;
  itemCount: number;
  packageCount: number;
  unavailableCount: number;
  noMatchCount: number;
}

export interface ShoppingPlan {
  id: string;
  mealPlanId: string;
  createdAt: string;
  updatedAt: string;
  source: ProductSource;
  version: number;
  mode: 'balanced' | 'cheapest';
  budgetCents: number | null;
  items: ShoppingItem[];
  totals: ShoppingTotals;
  /** Units this app placed in the Picnic cart for this plan, per product (for safe re-syncs). */
  cartApplied: Record<string, number>;
  cartSyncedAt: string | null;
}

export interface CartLine {
  productId: string;
  name: string;
  count: number;
  priceCents: number;
  unitQuantity?: string;
  imageUrl?: string | null;
  isUnavailable?: boolean;
}

export interface CartSnapshot {
  lines: CartLine[];
  totalCents: number;
  totalCount: number;
  /** Picnic's cart modification timestamp; required to start checkout. */
  mts: number | null;
  minimumOrderValueCents: number | null;
  selectedSlotId: string | null;
  source: ProductSource;
}

export interface CartOperation {
  productId: string;
  name: string;
  action: 'add' | 'remove';
  count: number;
  fromCount: number;
  toCount: number;
}

export interface CartDiff {
  operations: CartOperation[];
  unchanged: Array<{ productId: string; name: string; count: number }>;
  /** Items in the cart that this plan does not touch. */
  untouched: CartLine[];
  targetCounts: Record<string, number>;
  appliedAfter: Record<string, number>;
  /** Products already in the cart that count towards the plan, so they are not added twice. */
  alreadyInCart: Array<{ productId: string; name: string; count: number }>;
}

export interface DeliverySlotView {
  slotId: string;
  windowStart: string;
  windowEnd: string;
  cutOffTime: string;
  isAvailable: boolean;
  isSelected: boolean;
  minimumOrderValueCents: number | null;
  source: ProductSource;
}
